import type { RepositoryLocation } from "./location";

export interface ReadableCorpusProvider extends CorpusProvider {
  readDocumentBytes(binding: CorpusBinding, path: string): Promise<Buffer>;
  readDocumentText(binding: CorpusBinding, path: string): Promise<string>;
  readDocumentLines(binding: CorpusBinding, path: string): Promise<string[]>;
}

export interface CorpusAccess {
  provider(binding: CorpusBinding): ReadableCorpusProvider;
  readDocumentLines(binding: CorpusBinding, path: string): Promise<string[]>;
  discover(inputPath: string, profile: BuiltInDomainProfileId): Promise<RepositoryLocation>;
}
"},{"path":"domain/core/profiles/domainProfile.ts","text":"import type { SourceRange } from '../records/domain';

/** Built-in corpus profiles. Missing persisted values resolve to source-code. */
export type BuiltInDomainProfileId = 'source-code' | 'document';
export type DomainProfileId = BuiltInDomainProfileId | (string & {});
export type CorpusBinding =
  | { kind: 'git-worktree'; root: string; revision?: string }
  | { kind: 'filesystem-documents'; root: string };
export interface CorpusEntry { path: string; name: string; kind: 'directory' | 'file' }
export interface CorpusDirectoryListing { directory: string; entries: CorpusEntry[] }
export interface CorpusProvider {
  readonly kind: CorpusBinding['kind'];
  listDirectory(binding: CorpusBinding, directory: string): Promise<CorpusDirectoryListing>;
  readLines(binding: CorpusBinding, range: SourceRange): Promise<string[]>;
}

/** Shared source-pane rendering options. */
export interface ContentPresentation {
  syntaxHighlighting: 'code' | 'plain';
  markdownRendering: 'source' | 'terminal';
  wrap: boolean;
  sourceCompaction: boolean;
}
"},{"path":"domain/core/source/codeRepoService.ts","text":"import type { SourcePosition, SourceDefinitions } from './sourceNavigation';

export interface CodeRepoReference { projectId: string; sourceId: string }
export interface CodeRepoRequest { signal?: AbortSignal }
export interface CodeRepoFile { path: string; text: string; sha256: string; lspEnabled?: boolean }
export interface CodeRepoEntry { path: string; kind: 'file' | 'directory' }
export interface CodeRepoCommit { id: string; parents: string[]; author: string; date: string; message: string }
export interface CodeRepoFileChange {
  oldPath?: string; newPath?: string;
  status: 'added' | 'modified' | 'deleted' | 'renamed' | 'copied';
  additions?: number; deletions?: number; binary: boolean;
}
export interface CodeRepoSearchMatch { path: string; start: SourcePosition; end: SourcePosition; lineText: string }
export interface CodeRepoSearchQuery { text: string; paths: readonly string[]; caseSensitive?: boolean; regex?: boolean; limit?: number }
export interface CodeRepoDiffHunk { oldStart: number; oldCount: number; newStart: number; newCount: number; lines: string[] }
export interface CodeRepoFileDiff extends CodeRepoFileChange { hunks: CodeRepoDiffHunk[] }
export interface CodeRepoGitService {
  resolveCommit(repo: CodeRepoReference, ref: string, options?: CodeRepoRequest): Promise<CodeRepoCommit>;
  listCommits(repo: CodeRepoReference, options?: CodeRepoRequest & { path?: string; limit?: number }): Promise<CodeRepoCommit[]>;
  changedFiles(repo: CodeRepoReference, base: string, head: string, options?: CodeRepoRequest): Promise<CodeRepoFileChange[]>;
  diff(repo: CodeRepoReference, base: string, head: string, options?: CodeRepoRequest & { paths?: readonly string[] }): Promise<CodeRepoFileDiff[]>;
  readFileAt(repo: CodeRepoReference, commit: string, path: string, options?: CodeRepoRequest): Promise<CodeRepoFile>;
}
/** Browser-facing contract. Repo identity is explicit because one canvas can span repositories.
 * Implementations may delegate to HTTP, filesystem, search and language adapters.
 * All positions use zero-based UTF-16; diff hunk line numbers follow Git's one-based convention.
 */
export interface CodeRepoService {
  readonly available: boolean;
  readFile(repo: CodeRepoReference, path: string, options?: CodeRepoRequest & { reload?: boolean }): Promise<CodeRepoFile>;
  /** Warm mapped files without waiting for a source pane to open. */
  preloadFiles?(files: readonly { repo: CodeRepoReference; path: string; version: string }[]): void;
  listDirectory(repo: CodeRepoReference, path: string, options?: CodeRepoRequest): Promise<CodeRepoEntry[]>;
  search(repo: CodeRepoReference, query: CodeRepoSearchQuery, options?: CodeRepoRequest): Promise<{ matches: CodeRepoSearchMatch[]; truncated: boolean }>;
  definitions(repo: CodeRepoReference, anchor: { path: string; position: SourcePosition; sourceSha256: string }, options?: CodeRepoRequest): Promise<SourceDefinitions>;
  readonly git: CodeRepoGitService;
}
"},{"path":"domain/mapping/code-panel/codePanel.ts","text":"import { resolveNodeResources } from '../../core/diagrams/diagramResourceMappings';
import { diagramSource, type Diagram } from '../../core/diagrams/diagram';
import type { DiagramContentNode } from '../../core/diagrams/diagramContent';
import { diagramContentNodes } from '../../core/diagrams/diagramContentNodes';
import { mappingContentNodeId } from '../../core/presentation/diagramText';
import { sha256 } from '../../core/sha256';
import type { CodeRepoReference } from '../../core/source/codeRepoService';

/** Mapped source coordinates are inclusive, one-based lines, unlike LSP positions. */
export interface SourceRangeReference {
  repo: CodeRepoReference;
  path: string;
  startLine: number;
  endLine: number;
  rangeSha256: string;
}
export type MappedResource = { type: 'source-range'; target: SourceRangeReference };
export type MappedResourceType = MappedResource['type'];
export const DEFAULT_MAPPED_RESOURCE_TYPE: MappedResourceType = 'source-range';
export interface DiagramContext { diagram: Diagram; projectId: string }
export interface MappingOrigin {
  selectedNodeId: string; selectedLabel: string;
  mappedNodeId: string; mappedLabel: string; mappingId: string;
}
export interface ResolvedMapping { resource: MappedResource; origins: MappingOrigin[] }
export interface PanelContent {
  mappedResourceType: MappedResourceType;
  diagramId: string; revisionId: string; contentHash: string;
  selectedNodeIds: string[]; unmappedNodeIds: string[];
  items: ResolvedMapping[];
}
export interface SourceDisplayRange { startLine: number; endLine: number; items: ResolvedMapping[] }
export interface SourceDisplayFile {
  id: string; repo: CodeRepoReference; path: string; ranges: SourceDisplayRange[];
}

function sourceRangeIndex({ diagram, projectId }: DiagramContext): Map<string, ResolvedMapping[]> {
  const index = new Map<string, ResolvedMapping[]>();
  if (diagram.sourceContext.contentHash !== diagram.content.asciiSha256) throw new Error('Diagram mappings are stale');
  for (const { mapping, entity, range, binding } of diagramSource(diagram).entries()) {
    const nodeId = mappingContentNodeId(diagram.content, mapping);
    if (!nodeId || !entity || !range) continue;
    const list = index.get(nodeId) ?? [];
    list.push({ resource: { type: 'source-range', target: {
      repo: { projectId, sourceId: entity.sourceId ?? binding?.sourceId ?? '' },
      path: range.path, startLine: range.startLine, endLine: range.endLine,
      rangeSha256: sha256(range.originalLines.join('\n')),
    } }, origins: [{ selectedNodeId: '', selectedLabel: '', mappedNodeId: nodeId, mappedLabel: '', mappingId: mapping.id }] });
    index.set(nodeId, list);
  }
  return index;
}
export function sourceResourceIdentity(resource: MappedResource): string {
  const t = resource.target;
  return JSON.stringify([resource.type, t.repo.projectId, t.repo.sourceId, t.path, t.startLine, t.endLine, t.rangeSha256]);
}
/** Preserve diagram order, starting another section when files change or source lines go backwards. */
export function buildSourceRangeDisplayModel(items: readonly ResolvedMapping[]): SourceDisplayFile[] {
  const files: SourceDisplayFile[] = [];
  for (const item of items) {
    const t = item.resource.target;
    let file = files.at(-1);
    if (!file || file.path !== t.path || file.repo.projectId !== t.repo.projectId || file.repo.sourceId !== t.repo.sourceId
      || t.startLine < file.ranges.at(-1)!.startLine) {
      file = { id: sourceResourceIdentity(item.resource), repo: t.repo, path: t.path, ranges: [] };
      files.push(file);
    }
    const previous = file.ranges.at(-1);
    if (previous && t.startLine <= previous.endLine) {
      previous.endLine = Math.max(previous.endLine, t.endLine); previous.items.push(item);
    } else file.ranges.push({ startLine: t.startLine, endLine: t.endLine, items: [item] });
  }
  return files;
}
/** Domain handlers contain no React or file I/O. Renderers are registered in the UI. */
export const mappedResourceHandlers = {
  'source-range': { index: sourceRangeIndex, identity: sourceResourceIdentity, buildDisplayModel: buildSourceRangeDisplayModel },
} satisfies Record<MappedResourceType, unknown>;

export function resolveSelectedNodes(context: DiagramContext, selected: readonly DiagramContentNode[],
  mappedResourceType: MappedResourceType = DEFAULT_MAPPED_RESOURCE_TYPE) {
  const direct = mappedResourceHandlers[mappedResourceType].index(context);
  const { matches, unmappedNodeIds } = resolveNodeResources(diagramContentNodes(context.diagram.content), selected.map(node => node.id), direct);
  const results: ResolvedMapping[] = matches.flatMap(({ selectedNode, mappedNode, resources }) => resources.map(item => ({
    ...item, origins: item.origins.map(origin => ({ ...origin, selectedNodeId: selectedNode.id,
      selectedLabel: selectedNode.label, mappedNodeId: mappedNode.id, mappedLabel: mappedNode.label }))
  })));
  return { results, unmappedNodeIds };
}
export function handleNodeSelect(context: DiagramContext, nodes: readonly DiagramContentNode[],
  mappedResourceType: MappedResourceType = DEFAULT_MAPPED_RESOURCE_TYPE): PanelContent {
  nodes = [...nodes].sort((a, b) => a.line - b.line || a.startColumn - b.startColumn);
  const { results, unmappedNodeIds } = resolveSelectedNodes(context, nodes, mappedResourceType);
  const combined = new Map<string, ResolvedMapping>();
  for (const result of results) {
    const key = mappedResourceHandlers[mappedResourceType].identity(result.resource);
    const prior = combined.get(key);
    if (prior) prior.origins.push(...result.origins); else combined.set(key, { ...result, origins: [...result.origins] });
  }
  return { mappedResourceType, diagramId: context.diagram.id, revisionId: context.diagram.content.revisionId,
    contentHash: context.diagram.content.asciiSha256, selectedNodeIds: [...new Set(nodes.map(n => n.id))],
    unmappedNodeIds, items: [...combined.values()] };
}
"},{"path":"infrastructure/core/corpus/corpus.ts","text":"import {
  lstat,
  readdir,
  readFile,
  realpath,
  stat
} from "node:fs/promises";
import path from "node:path";
import type { CorpusBinding, CorpusDirectoryListing, CorpusProvider } from "../../../domain/core/profiles/domainProfile";
import type { SourceRange } from "../../../domain/core/records/domain";

function relativeSegments(value: string, label: string): string[] {
  if (value.includes("\0") || value.includes("\\")) {
    throw new Error(`${label} path is invalid`);
  }
  if (path.posix.isAbsolute(value) || path.win32.isAbsolute(value)) {
    throw new Error(`${label} path must be relative`);
  }
  const segments = value === "" ? [] : value.split("/");
  if (segments.some((segment) => !segment || segment === "." || segment === "..")) {
    throw new Error(`${label} path is invalid`);
  }
  return segments;
}

async function canonicalBindingRoot(binding: CorpusBinding, expectedKind: CorpusBinding["kind"]): Promise<string> {
  if (binding.kind !== expectedKind) {
    throw new Error(`corpus provider ${expectedKind} cannot read ${binding.kind}`);
  }
  const root = await realpath(binding.root).catch(() => null);
  if (!root || !(await stat(root)).isDirectory()) {
    throw new Error(`corpus root is not a directory: ${path.resolve(binding.root)}`);
  }
  return root;
}

async function resolveWithoutSymlinks(
  root: string,
  relativePath: string,
  label: string
): Promise<string> {
  const segments = relativeSegments(relativePath, label);
  let resolved = root;
  for (const segment of segments) {
    resolved = path.join(resolved, segment);
    const info = await lstat(resolved).catch(() => null);
    if (!info) throw new Error(`unknown ${label} path: ${relativePath}`);
    if (info.isSymbolicLink()) {
      throw new Error(label === "corpus directory"
        ? "symbolic-link directories cannot be traversed"
        : "symbolic-link corpus file paths cannot be traversed");
    }
  }
  if (resolved !== root && !resolved.startsWith(`${root}${path.sep}`)) {
    throw new Error(`${label} path escapes corpus root`);
  }
  return resolved;
}

class FilesystemCorpusProvider implements CorpusProvider {
  constructor(readonly kind: CorpusBinding["kind"]) { }

  async listDirectory(
    binding: CorpusBinding,
    directory: string
  ): Promise<CorpusDirectoryListing> {
    const root = await canonicalBindingRoot(binding, this.kind);
    const directoryPath = await resolveWithoutSymlinks(root, directory, "corpus directory");
    if (!(await stat(directoryPath)).isDirectory()) {
      throw new Error(`corpus path is not a directory: ${directory}`);
    }
    const entries = (await readdir(directoryPath, { withFileTypes: true }))
      .filter((entry) => entry.name !== ".git")
      .map((entry) => ({
        path: path.relative(root, path.join(directoryPath, entry.name)).split(path.sep).join("/"),
        name: entry.name,
        kind: entry.isDirectory() && !entry.isSymbolicLink()
          ? "directory" as const
          : "file" as const
      }))
      .sort((left, right) => (
        (left.kind === right.kind ? 0 : left.kind === "directory" ? -1 : 1)
        || left.name.localeCompare(right.name, undefined, { sensitivity: "base" })
        || left.path.localeCompare(right.path)
      ));
    return { directory: relativeSegments(directory, "corpus directory").join("/"), entries };
  }

  async readLines(binding: CorpusBinding, range: SourceRange): Promise<string[]> {
    if (!Number.isInteger(range.startLine) || !Number.isInteger(range.endLine)
      || range.startLine < 1 || range.endLine < range.startLine) {
      throw new Error(`invalid evidence range for ${range.path}`);
    }
    const lines = await this.readDocumentLines(binding, range.path);
    return lines.slice(range.startLine - 1, Math.min(range.endLine, lines.length));
  }

  async readDocumentLines(binding: CorpusBinding, relativePath: string): Promise<string[]> {
    return (await this.readDocumentText(binding, relativePath)).split(/\r?\n/);
  }

  async readDocumentText(binding: CorpusBinding, relativePath: string): Promise<string> {
    return (await this.readDocumentBytes(binding, relativePath)).toString("utf8");
  }

  async readDocumentBytes(binding: CorpusBinding, relativePath: string): Promise<Buffer> {
    const root = await canonicalBindingRoot(binding, this.kind);
    const filePath = await resolveWithoutSymlinks(root, relativePath, "corpus file");
    if (!(await stat(filePath)).isFile()) throw new Error(`corpus path is not a file: ${relativePath}`);
    return readFile(filePath);
  }
}

export type ReadableCorpusProvider = CorpusProvider & {
  readDocumentBytes(binding: CorpusBinding, relativePath: string): Promise<Buffer>;
  readDocumentText(binding: CorpusBinding, relativePath: string): Promise<string>;
  readDocumentLines(binding: CorpusBinding, relativePath: string): Promise<string[]>;
};

const providers: Record<CorpusBinding["kind"], ReadableCorpusProvider> = {
  "git-worktree": new FilesystemCorpusProvider("git-worktree"),
  "filesystem-documents": new FilesystemCorpusProvider("filesystem-documents")
};

export function corpusProvider(binding: CorpusBinding): ReadableCorpusProvider {
  return providers[binding.kind];
}

export async function readCorpusDocumentLines(
  binding: CorpusBinding,
  relativePath: string
): Promise<string[]> {
  return corpusProvider(binding).readDocumentLines(binding, relativePath);
}
"},{"path":"infrastructure/core/persistence/repositoryRegistry.ts","text":"import { captureGitHunks } from './repositoryHunks';
import type { RepositoryContext } from '../../../domain/core/repositories/repository';
import path from 'node:path';
import { createHash } from 'node:crypto';
import type { RepositoryRegistry } from '../../../application/core/ports/repositoryRegistry';
import type { Repository } from '../../../domain/core/repositories/repository';
import { repositoryContextSchema } from '../../../domain/core/repositories/repository';
import type { ProjectRecord } from '../../../domain/core/records/domain';
import { discoverRepository, execFileAsync, readJsonIfExists, writeJsonAtomic } from './shared';

const queues = new Map<string, Promise<unknown>>();
export class GitRepositoryRegistry implements RepositoryRegistry {
  private readonly file: string;
  constructor(storeRoot: string, private readonly checkoutRoot: string) { this.file = path.join(storeRoot, 'project.json'); }
  private async serial<T>(run: () => Promise<T>): Promise<T> {
    const next = (queues.get(this.file) ?? Promise.resolve()).catch(() => {}).then(run);
    queues.set(this.file, next);
    try { return await next; } finally { if (queues.get(this.file) === next) queues.delete(this.file); }
  }
  private async project() {
    const project = await readJsonIfExists<ProjectRecord>(this.file);
    if (!project) throw Error('Project is not initialized');
    return project;
  }
  private async discover(root: string, name?: string): Promise<Repository> {
    const location = await discoverRepository(root);
    return { id: `repo-${createHash('sha256').update(location.repositoryIdentity).digest('hex').slice(0, 24)}`,
      name: name?.trim() || path.basename(location.checkoutRoot), identity: location.repositoryIdentity, checkoutRoots: [location.checkoutRoot] };
  }
  /** Backfill only repository identities we can actually discover. Non-Git projects stay unassigned. */
  async initialize() {
    return this.serial(async () => {
      const project = await this.project();
      if (project.repositories !== undefined) return project;
      const repositories: Repository[] = [];
      const roots = new Set([this.checkoutRoot, ...(project.sources ?? []).filter(s => s.corpus.kind === 'git-worktree').map(s => s.corpus.root)]);
      for (const root of roots) {
        const repository = await this.discover(root).catch(() => undefined);
        if (!repository) continue;
        const prior = repositories.find(r => r.id === repository.id);
        if (prior) prior.checkoutRoots = [...new Set([...prior.checkoutRoots, ...repository.checkoutRoots])];
        else repositories.push(repository);
      }
      const next = { ...project, repositories };
      await writeJsonAtomic(this.file, next);
      return next;
    });
  }
  async list() { return (await this.initialize()).repositories ?? []; }
  async register(input: { path: string; name?: string }) {
    const found = await this.discover(input.path, input.name);
    await this.initialize();
    return this.serial(async () => {
      const project = await this.project(), repositories = [...(project.repositories ?? [])];
      const index = repositories.findIndex(repository => repository.id === found.id), prior = repositories[index];
      const repository = { ...found, name: input.name?.trim() || prior?.name || found.name,
        checkoutRoots: [...new Set([...(prior?.checkoutRoots ?? []), ...found.checkoutRoots])] };
      if (index < 0) repositories.push(repository); else repositories[index] = repository;
      await writeJsonAtomic(this.file, { ...project, repositories, updatedAt: new Date().toISOString() });
      return repository;
    });
  }
  private async availableRoot(repository: Repository) {
    let root: string | undefined;
    // A saved worktree may have been removed since the repository was registered.
    // The current checkout is also usable, but only for the same Git repository.
    for (const candidate of new Set([...repository.checkoutRoots, this.checkoutRoot])) {
      const location = await discoverRepository(candidate).catch(() => undefined);
      if (location?.repositoryIdentity === repository.identity) { root = location.checkoutRoot; break; }
    }
    if (!root) throw Error('Repository checkout is unavailable');
    return root;
  }
  async resolveCheckoutRoot(repositoryId: string) {
    const repository = (await this.list()).find(repository => repository.id === repositoryId);
    if (!repository) throw Error('Unknown repositoryId');
    return this.availableRoot(repository);
  }
  async captureHunks(context: RepositoryContext) {
    repositoryContextSchema.parse(context);
