      onScroll={(event) => {
        const position = { top: event.currentTarget.scrollTop, left: event.currentTarget.scrollLeft };
        if (position.top === 0 && position.left === 0 && !event.currentTarget.getClientRects().length) return;
        props.scrollState?.write(position);
